<?php

namespace ThePHPBench\PHPFUI\Record\Definition;

/**
 * Autogenerated canonical benchmark definition.
 *
 * @property int $simple_id MySQL type integer
 * @property string $title MySQL type varchar(128)
 */
abstract class Simple extends \PHPFUI\ORM\Record
	{
	protected static bool $autoIncrement = false;

	protected static array $fields = [];

	protected static array $primaryKeys = ['simple_id'];

	protected static string $table = 'simple_records';

	public function initFieldDefinitions() : static
		{
		if (! \count(static::$fields))
			{
			static::$fields = [
				'simple_id' => new \PHPFUI\ORM\FieldDefinition('integer', 'int', 0, false),
				'title' => new \PHPFUI\ORM\FieldDefinition('varchar(128)', 'string', 128, false),
			];
			}

		return $this;
		}
	}
